import React, { useState } from 'react';

function CartPage({ cart, onClearCart, onPlaceOrder }) {
    const [successMessage, setSuccessMessage] = useState(''); // State for success message

    const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

    const handlePlaceOrder = async () => {
        try {
            await onPlaceOrder(); // Call the `onPlaceOrder` function
            setSuccessMessage('Order placed successfully!'); // Set success message
            setTimeout(() => setSuccessMessage(''), 3000); // Clear the message after 3 seconds
        } catch (err) {
            console.error('Error placing order:', err.message);
        }
    };

    return (
        <div className="cart-container bg-gray-100 min-h-screen p-8">
            <h1 className="text-4xl font-bold text-green-600 text-center mb-8">
                Your Cart
            </h1>

            {/* Show success message */}
            {successMessage && (
                <div className="bg-green-200 text-green-800 p-4 rounded-lg text-center mb-4">
                    {successMessage}
                </div>
            )}

            {cart.length === 0 ? (
                <p className="text-center text-gray-500 text-lg">
                    Your cart is empty. Start shopping now!
                </p>
            ) : (
                <>
                    <div className="cart-items max-w-5xl mx-auto grid gap-6">
                        {cart.map((item) => (
                            <div
                                key={item.id}
                                className="flex items-center bg-white p-6 rounded-lg shadow-md"
                            >
                                <img
                                    src={item.image}
                                    alt={item.name}
                                    className="w-24 h-24 object-cover rounded-md"
                                />
                                <div className="ml-6 flex-1">
                                    <h3 className="text-lg font-semibold text-gray-800">
                                        {item.name}
                                    </h3>
                                    <p className="text-gray-600">
                                        ${item.price} x {item.quantity}
                                    </p>
                                    <p className="text-green-600 font-bold">
                                        Total: ${item.price * item.quantity}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="cart-summary max-w-5xl mx-auto mt-10 bg-white p-6 rounded-lg shadow-md">
                        <h2 className="text-2xl font-bold text-gray-800">
                            Total Amount: <span className="text-green-600">${totalAmount.toFixed(2)}</span>
                        </h2>
                        <button
                            onClick={handlePlaceOrder}
                            className="mt-4 w-full bg-green-500 text-white py-3 px-6 rounded-lg font-semibold hover:bg-green-600 transition duration-200"
                        >
                            Place Order
                        </button>
                    </div>
                </>
            )}
        </div>
    );
}

export default CartPage;
